import React, { useState } from 'https://cdn.jsdelivr.net/npm/react@17.0.2/+esm';
import ReactDOM from 'https://cdn.jsdelivr.net/npm/react-dom@17.0.2/+esm';
import { Button, Container, TextField, Typography, Chip, Divider, Box }
  from 'https://cdn.jsdelivr.net/npm/@material-ui/core@4.12.4/+esm';

const MyCustomComponent = ({ data, updateData, runQuery }) => {
  const [inputVal, setInputVal] = useState('');

  return (
    <Container style={{ padding: 20, display: 'flex', flexDirection: 'column', gap: 16 }}>

      {/* 1. Show current data object */}
      <Typography variant="h6">{data.title || '(no title)'}</Typography>
      <Box style={{ background: '#f5f5f5', padding: 8, borderRadius: 4 }}>
        <Typography variant="caption">data snapshot:</Typography>
        <pre style={{ margin: 0, fontSize: 11 }}>{JSON.stringify(data, null, 2)}</pre>
      </Box>

      <Divider />

      {/* 2. updateData — write a new title */}
      <TextField
        label="New title"
        size="small"
        variant="outlined"
        value={inputVal}
        onChange={(e) => setInputVal(e.target.value)}
      />
      <Button
        variant="contained"
        color="primary"
        onClick={() => updateData({ ...data, title: inputVal })}
      >
        Update title
      </Button>

      {/* 3. Original button from your snippet */}
      <Button
        color="secondary"
        variant="outlined"
        onClick={() => updateData({ ...data, title: 'Hello World!!' })}
      >
        {data.buttonText || 'Reset title'}
      </Button>

      <Divider />

      {/* 4. runQuery — fire a named query */}
      <Typography variant="caption">
        Query name to run: <strong>{data.queryName || '(set data.queryName)'}</strong>
      </Typography>
      <Button
        variant="outlined"
        onClick={() => data.queryName && runQuery(data.queryName)}
        disabled={!data.queryName}
      >
        Run query
      </Button>

      {/* 5. Show a chip per data key so you can see what's exposed */}
      <Box style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
        {Object.keys(data).map((k) => (
          <Chip key={k} label={`${k}: ${JSON.stringify(data[k])}`} size="small" />
        ))}
      </Box>

    </Container>
  );
};

const ConnectedComponent = Tooljet.connectComponent(MyCustomComponent);
ReactDOM.render(<ConnectedComponent />, document.body);
